-- Extra queries for the viva: recursive CTE and outer joins.  Run: mysql -u root -p ticketdb < db/extra_queries.sql
USE ticketdb;

-- Recursive query: a day-by-day calendar (generated by the recursive CTE) joined to the shows scheduled on each day
WITH RECURSIVE calendar AS (
  SELECT DATE('2026-12-01') AS day                              -- anchor member
  UNION ALL
  SELECT day + INTERVAL 1 DAY FROM calendar WHERE day < '2026-12-16'   -- recursive member, stops at the end date
)
SELECT c.day,
       COUNT(sh.show_id)                  AS shows,
       GROUP_CONCAT(e.title SEPARATOR ', ') AS events
FROM calendar c
LEFT JOIN shows sh ON DATE(sh.start_time) = c.day
LEFT JOIN events e ON e.event_id = sh.event_id
GROUP BY c.day
ORDER BY c.day;

-- Outer join: every event with its confirmed ticket count, including events that have no shows or no bookings
SELECT e.title, e.status, COUNT(bs.show_seat_id) AS tickets_sold
FROM events e
LEFT JOIN shows sh         ON sh.event_id = e.event_id
LEFT JOIN bookings b       ON b.show_id = sh.show_id AND b.status = 'CONFIRMED'
LEFT JOIN booking_seats bs ON bs.booking_id = b.booking_id
GROUP BY e.event_id, e.title, e.status
ORDER BY tickets_sold DESC, e.title;
